function urljump(url,zwcode,zwyear,id){
    var uid = "";
    $("#url").val(url);
    $("#id").val(id);
    //检测是否登录
    if(uid==""){
      window.open('/index/user/login?zwcode=gj&c9925760d0265fc151c7d5406a0f420e');
      return false;
    }else{
      var tjurl = "/"+zwcode+'/'+zwyear+'/'+url+id+'.html';      
      window.location.href=tjurl;
    } 
  }
